using Avalonia.Controls;
using Avalonia.Media;
namespace TritStudio.App;

public sealed partial class MainWindow
{
    // Opt-in only: architecture and launch fields, not every label in the application.
    private static Control HelpField(string label, Control input, string help)
    {
        input.Tag = label;
        var name = new TextBlock { Text = label, Foreground = Muted, FontSize = 12, Tag = "parameter-help" };
        ToolTip.SetTip(name, new TextBlock { Text = help, MaxWidth = 380, TextWrapping = TextWrapping.Wrap });
        ToolTip.SetShowDelay(name, 2000);
        ToolTip.SetBetweenShowDelay(name, 0); // Each label waits again, even after another tooltip was just closed.
        return Column(name, input);
    }
    private const string WidthHelp = "Ширина скрытого представления одного токена. Больше ширина: больше параметров, вычислений и памяти. Должна делиться на число голов и размер группы квантования. Меняется только при создании новой сети.";
    private const string FfnHelp = "FFN: внутренняя ширина блока обработки токена после внимания. Увеличение даёт сети больше параметров, но повышает время и память обучения. Должна делиться на размер группы квантования. Это не длина текста.";
    private const string LayersHelp = "Количество последовательных блоков сети. Больше слоёв увеличивает глубину обработки, размер модели, время и память. Само по себе не гарантирует лучшие ответы. Архитектура уже созданной модели не изменяется.";
    private const string HeadsHelp = "Количество голов внимания, параллельно обрабатывающих разные представления контекста. Ширина должна делиться на головы, а ширина одной головы быть чётной для RoPE. Больше голов при той же ширине не означает больше знаний.";
    private const string KvHelp = "Количество общих голов ключей и значений (K/V). Может быть меньше числа голов внимания: это GQA, которое уменьшает KV-кеш. Должно делить число голов внимания без остатка.";
    private const string ContextHelp = "Максимальная длина контекста сети: запрос, история и ответ вместе. Здесь токены байтовые: кириллическая буква обычно занимает два токена, а не один. Больший контекст не обучает долгой памяти сам по себе и увеличивает возможные затраты памяти.";
    private const string PlanesHelp = "Число троичных плоскостей, которыми приближаются веса. Больше плоскостей обычно точнее передаёт веса, но увеличивает файл и стоимость квантования. Мастер-веса для обучения всё равно FP32; это не 2-битное обучение целиком.";
    private const string GroupHelp = "Число весов, использующих общий масштаб квантования. Меньшая группа даёт больше отдельных масштабов и больший расход служебных данных. Размер должен делить ширину и FFN; менять можно только для новой модели.";
    private const string ThresholdHelp = "Порог обнуления веса внутри каждой троичной плоскости относительно её масштаба. Малые по модулю значения становятся нулём. Параметр влияет на точность квантования, а не на уверенность ответа. Допустимо от 0 до 1.";
    private const string StepsHelp = "Количество дополнительных шагов оптимизатора в этом запуске, не число эпох. На каждом шаге выбирается пакет примеров. 2000 означает ещё 2000 обновлений текущих весов. Нулевое создание модели отдельно выполняет ровно 0 шагов.";
    private const string RateHelp = "Learning rate (LR): масштаб обновления весов. Слишком маленькое значение может почти не обучить случайную сеть за выбранное число шагов; слишком большое может сделать обучение нестабильным. 0,001 = 1e-3; 0,0003 = 3e-4. Принимаются точка, запятая и научная запись. Меньше не всегда лучше.";
    private const string BatchHelp = "Число примеров на один шаг оптимизатора: от 1 до 64. Больший пакет может лучше загрузить GPU, но требует больше памяти. При одинаковом числе шагов модель увидит больше примеров. Увеличение пакета не гарантирует качество или ускорение; LR автоматически не меняется.";
    private const string LengthHelp = "Верхняя граница длины учебной последовательности, не может быть больше контекста выбранной сети. Реальный пакет может быть короче. История сокращается целыми обменами, целевой ответ не обрезается молча. Байтовые токены, не слова; большая длина особенно увеличивает память внимания.";
    private const string PublishHelp = "Через сколько шагов сохранять снимок весов и обновлять доступную чату ревизию. Меньше интервал: меньше потеря при сбое, но больше записей и остановок на проверку. Последний неполный интервал тоже сохраняется. История ограничена 128 снимками; очистка доступна в обслуживании.";
}
